subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "eps_actual": {
      "maxLength": 16,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "eps_estimate": {
      "maxLength": 16,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "quarter": {
      "maxLength": 16,
      "pattern": "^Q[1-4]-?[0-9]{2,4}$",
      "type": "string"
    },
    "revenue_actual": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "revenue_estimate": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "snapshot": {
      "description": "Earnings transcripts, 8-K filings, fundamentals, and key metrics keyed by data type",
      "type": "object"
    },
    "ticker": {
      "maxLength": 12,
      "pattern": "^[A-Za-z0-9._-]+$",
      "type": "string"
    }
  },
  "required": [
    "ticker",
    "quarter",
    "snapshot"
  ],
  "type": "object"
}
